import { pronunciationAudio } from '../../../lib/api';

/**
 * The audio of a vocabulary item (MEM-39), generated by Kokoro on the API.
 * The browser never calls the API: this route forwards the request with the
 * session's token. 404 while there is none (the page then falls back on the
 * browser's speech synthesis). The address carries a hash of the English
 * (lib/pronunciation-url.ts), so the audio can stay in the browser's cache.
 */
export async function GET(_request: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const audio = await pronunciationAudio(id);
  if (!audio.ok) return new Response(null, { status: audio.status, headers: { 'Cache-Control': 'no-store' } });
  return new Response(audio.body, {
    headers: {
      'Content-Type': audio.mimeType,
      ...(audio.length && { 'Content-Length': audio.length }),
      'Cache-Control': 'private, max-age=604800',
    },
  });
}
